import http from 'http';
import axios from './index.js';
import formidable from 'formidable';
import getStream from 'get-stream';
import assert from 'assert';

const handleFormData = (req) => new Promise((resolve, reject) => {
  const form = new formidable.IncomingForm();
  form.parse(req, (err, fields, files) => err ? reject(err) : resolve({fields, files}));
});

const server = http.createServer(async (req, res) => {
  if (req.url === '/blob') {
    res.end(await getStream(req));
    return;
  }
  const {fields, files} = await handleFormData(req);
  res.end(JSON.stringify({fields, files}));
});

await new Promise(resolve => server.listen(0, resolve));
const url = 'http://localhost:' + server.address().port;

const form = new FormData();
const blobContent = 'blob-content';
const blob = new Blob([blobContent], {type: 'image/jpeg'});
form.append('foo1', 'bar1');
form.append('foo2', 'bar2');
form.append('file1', blob);

const {data} = await axios.post(url, form, {maxRedirects: 0});
assert.deepStrictEqual(data.fields, {foo1: 'bar1', foo2: 'bar2'});
assert.strictEqual(data.files.file1.mimetype, 'image/jpeg');
assert.strictEqual(data.files.file1.originalFilename, 'blob');
assert.strictEqual(data.files.file1.size, Buffer.byteLength(blobContent));

const blobResponse = await axios.post(url + '/blob', blob, {maxRedirects: 0});
assert.strictEqual(blobResponse.data, blobContent);

server.close();
console.log('native FormData + Blob OK');

